files.content:
html,
body {
  min-height: 100dvh;
}

body {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  background: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
  min-block-size: 100dvh;
}

.wrapper {
  font-family: serif;
  inline-size: 100%;
  block-size: 100dvh;
}

.mix {
  display: flex;
  justify-content: center;
  align-items: center;
  background-image: url(https://picsum.practicum-team.ru/random-image);
  background-position: center;
  background-size: cover;
  block-size: 100%;
}

img {
  inline-size: 80%;

  /* пишите ваш код здесь */
  mix-blend-mode: multiply;
}
